    background: "#ede8f8",
    borderColor: "#a89adc",
    color: "#3c3478"
  },
  submitBtn: {
    width: "100%",
    background: "#3a2a20",
    border: "none",
    borderRadius: 8,
    padding: "13px",
    color: "#fdf0e8",
    fontSize: 13,
    fontFamily: "'Inter',sans-serif",
    letterSpacing: "0.08em",
    textTransform: "uppercase",
    cursor: "pointer",
    marginTop: 4,
    transition: "opacity 0.15s"
  }
};
