import { useState } from "react";
import { TextField, MenuItem } from "@mui/material";
import emailjs from "@emailjs/browser";
import { EMAILJS_CONFIG } from "../emailConfig";

const DIETARY_OPTIONS = [
  "None", "Vegetarian", "Vegan", "Gluten free",
  "Dairy free", "Nut allergy", "Halal", "Ketogenic (Keto Diet)", "Other",
  
];

function formatDietaryRequirements(dietary) {
  const selected = (dietary || []).filter(Boolean);
  if (!selected.length || selected.includes("None")) return "No dietary requirements";
  return selected.join(", ");
}

function buildReceiptLine(label, value) {
  return { label, value };
}

const FORMSPREE_ENDPOINT = "https://formspree.io/f/xqejvebz";

const BRIDGE_IMG = "data:image/png;base64,";
const VENUE_IMG  = "data:image/png;base64,";
const MAP_IMG    = "data:image/png;base64,";

emailjs.init(EMAILJS_CONFIG.publicKey);

const globalStyles = `
  @import url('https://fonts.googleapis.com/css2?family=Pinyon+Script&family=Lora:ital,wght@0,400;0,500;1,400&family=Inter:wght@300;400;500&display=swap');
  * { box-sizing: border-box; }
  body { margin: 0; background: #fdf6f0; }

  .rsvp-btn {
    display: inline-block;
    border: none;
    border-radius: 999px;
    padding: 10px 28px;
    font-size: 10px;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #5a3a2e;
    background: #f5e8e2;
    cursor: pointer;
    font-family: 'Inter', sans-serif;
    text-decoration: none;
    transition: background 0.2s, color 0.2s;
  }
  .rsvp-btn:hover { background: #e8cfc4; }

  @keyframes fadeUp {
    from { opacity: 0; transform: translateY(18px); }
    to   { opacity: 1; transform: translateY(0); }
  }
  .fade-up { animation: fadeUp 0.9s ease-out both; }
  .delay-1 { animation-delay: 0.15s; }
  .delay-2 { animation-delay: 0.3s; }
  .delay-3 { animation-delay: 0.45s; }

  input:focus, textarea:focus, select:focus {
    outline: none;
    border-color: #c4a89a !important;
    box-shadow: 0 0 0 2px rgba(196,168,154,0.15);
  }

  @media (max-width: 640px) {
    .when-where-grid { flex-direction: column !important; }
    .transport-grid  { grid-template-columns: 1fr 1fr !important; }
    .where-dress-grid { flex-direction: column !important; }
  }
`;

// ── SVG Decorations ───────────────────────────────────────────────────────────

function CosmosFlower({ style }) {
  return (
    <svg viewBox="0 0 180 220" style={{ display: "block", ...style }} fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="M90 210 Q85 170 80 140 Q75 110 82 80" stroke="#6b8a5e" strokeWidth="2.5" strokeLinecap="round" fill="none"/>
      <path d="M82 130 Q60 118 55 100 Q70 105 82 120" fill="#7fa86a" opacity="0.8"/>
      <path d="M83 105 Q100 92 105 75 Q92 82 83 98" fill="#7fa86a" opacity="0.7"/>
      {[0,45,90,135,180,225,270,315].map((deg, i) => (
        <ellipse key={i}
          cx={90 + Math.cos((deg - 90) * Math.PI / 180) * 28}
          cy={62 + Math.sin((deg - 90) * Math.PI / 180) * 28}
          rx="14" ry="24"
          transform={`rotate(${deg}, ${90 + Math.cos((deg-90)*Math.PI/180)*28}, ${62 + Math.sin((deg-90)*Math.PI/180)*28})`}
          fill={i % 2 === 0 ? "#f0a08a" : "#f4b8a2"} opacity="0.82"/>
      ))}
      <circle cx="90" cy="62" r="10" fill="#f5d67a"/>
      <circle cx="90" cy="62" r="6"  fill="#e8b840" opacity="0.9"/>
      <circle cx="90" cy="62" r="3"  fill="#c89230"/>
    </svg>
  );
}

function PinkFlower({ size = 60, style }) {
  return (
    <svg viewBox="0 0 100 100" style={{ display: "block", width: size, height: size, ...style }} fill="none" xmlns="http://www.w3.org/2000/svg">
      {[0,72,144,216,288].map((deg, i) => (
        <ellipse key={i}
          cx={50 + Math.cos((deg-90)*Math.PI/180)*22}
          cy={50 + Math.sin((deg-90)*Math.PI/180)*22}
          rx="13" ry="20"
          transform={`rotate(${deg}, ${50+Math.cos((deg-90)*Math.PI/180)*22}, ${50+Math.sin((deg-90)*Math.PI/180)*22})`}
          fill="#f4a8b8" opacity="0.82"/>
      ))}
      <circle cx="50" cy="50" r="11" fill="#fde9ee"/>
      <circle cx="50" cy="50" r="6"  fill="#f9d4dc"/>
      <circle cx="50" cy="50" r="3"  fill="#f0c4cc"/>
      {[0,60,120,180,240,300].map((deg,i) => (
        <circle key={i}
          cx={50 + Math.cos((deg-90)*Math.PI/180)*7}
          cy={50 + Math.sin((deg-90)*Math.PI/180)*7}
          r="1.5" fill="#e8a0b0" opacity="0.8"/>
      ))}
    </svg>
  );
}

function WaterBlob({ style, color = "#f0c8b8", width = 180, height = 110 }) {
  return (
    <svg viewBox="0 0 180 110" style={{ display:"block", width, height, ...style }} fill="none" xmlns="http://www.w3.org/2000/svg">
      <ellipse cx="90" cy="70" rx="82" ry="36" fill={color} opacity="0.38"/>
      <ellipse cx="60" cy="50" rx="46" ry="34" fill={color} opacity="0.30"/>
      <ellipse cx="120" cy="45" rx="40" ry="30" fill={color} opacity="0.28"/>
      <ellipse cx="85" cy="32" rx="32" ry="22" fill={color} opacity="0.22"/>
    </svg>
  );
}

// Tilted photo — no frame, just image at angle with shadow
function TiltedPhoto({ src, rotate = -2, style }) {
  return (
    <div style={{
      transform: `rotate(${rotate}deg)`,
      width: 300,
      height: 270,
      flexShrink: 0,
      boxShadow: "0 4px 18px rgba(0,0,0,0.13)",
      borderRadius: 2,
      overflow: "hidden",
      ...style,
    }}>
      <img src={src} alt="" style={{ display:"block", width:"100%", height:"100%", objectFit:"cover" }}/>
    </div>
  );
}

// ── Guest row ────────────────────────────────────────────────────────────────

function GuestRow({ index, guest, onChange }) {
  const label = index === 0 ? "Your details" : `Guest ${index}`;
  return (
    <div style={{ borderTop: index===0?"none":"1px solid #ede4dc", paddingTop: index===0?0:"1rem", marginTop: index===0?0:"0.5rem" }}>
      <p style={{ fontFamily:"'Inter',sans-serif", fontSize:11, letterSpacing:"0.1em", textTransform:"uppercase", color:"#9b7b6a", margin:"0 0 0.75rem", fontWeight:500 }}>{label}</p>
      <Field label="Full name">
        <input style={S.input} type="text" placeholder={index===0?"e.g. Sarah Johnson":`Guest ${index} name`}
          value={guest.name} onChange={e => onChange(index,{...guest,name:e.target.value})} required={index===0}/>
      </Field>
      <Field label="">
        <TextField
          select fullWidth label="Dietary Requirements"
          value={guest.dietary?.[0] || ""}
          onChange={(e) => onChange(index, { ...guest, dietary: e.target.value ? [e.target.value] : [] })}
        >
          <MenuItem value=""><em>Select one</em></MenuItem>
          {DIETARY_OPTIONS.map((option) => (
            <MenuItem key={option} value={option}>{option}</MenuItem>
          ))}
        </TextField>
      </Field>
    </div>
  );
}

// ── Main ─────────────────────────────────────────────────────────────────────

const defaultGuest = () => ({ name:"", dietary:[] });

export default function WeddingRSVP() {
  const [attending, setAttending]   = useState(null);
  const [email, setEmail]           = useState("");
  const [guestCount, setGuestCount] = useState(1);
  const [guests, setGuests]         = useState([defaultGuest()]);
  const [message, setMessage]       = useState("");
  const [submitted, setSubmitted]   = useState(false);
  const [loading, setLoading]       = useState(false);
  const [error, setError]           = useState(null);
  const [showForm, setShowForm]     = useState(false);

  function handleGuestCountChange(count) {
    const n = Math.max(1, Math.min(5, Number(count)));
    setGuestCount(n);
    setGuests(prev => {
      const next = [...prev];
      while (next.length < n) next.push(defaultGuest());
      return next.slice(0, n);
    });
  }
  function handleGuestChange(i, updated) {
    setGuests(prev => prev.map((g, idx) => idx===i ? updated : g));
  }

  async function handleSubmit(e) {
    e.preventDefault();
    setLoading(true); setError(null);
    const templatePayload = {
      email,
      name:      guests[0]?.name,
      dietary:   formatDietaryRequirements(guests[0]?.dietary),
      attending,
      guests: attending === 'yes'
        ? guests.map((g, i) =>
            `${i === 0 ? 'Primary' : `Guest ${i}`}: ${g.name} (${formatDietaryRequirements(g.dietary)})`
          ).join('\n')
        : null,
      message: message || 'None',
    };

    try {
      const templateId = attending === 'yes'
        ? EMAILJS_CONFIG.confirmTemplateId
        : EMAILJS_CONFIG.declineTemplateId;
      const res = await fetch(FORMSPREE_ENDPOINT, {
        method:"POST",
        headers:{"Content-Type":"application/json", Accept:"application/json"},
        body:JSON.stringify(templatePayload)
      });
      if (!res.ok) throw new Error();
      try {
        await emailjs.send(EMAILJS_CONFIG.serviceId, templateId, templatePayload);
      } catch {
        console.error("EmailJS send failed..");
      }
      setSubmitted(true);
    } catch {
      setError("Something went wrong. Please try again or contact us directly.");
    } finally {
      setLoading(false);
    }
  }

  const canSubmit = guests[0]?.name && email && attending && !loading;
  const receiptGuests = guests.map((guest, index) => ({
    label: index === 0 ? "Primary guest" : `Guest ${index}`,
    name: guest.name || "Name not provided",
    dietary: formatDietaryRequirements(guest.dietary),
  }));
  const receiptMessage = message?.trim() || "None";

  if (submitted) return (
    <div style={S.page}>
      <style>{globalStyles}</style>
      <div style={{ ...S.hero, minHeight:"60vh", padding:"3rem 1.5rem" }}>
        <div style={S.successWrap}>
          <h1 style={S.scriptNames}>{attending==="yes"?"We'll see you there!":"We'll miss you"}</h1>
          <div style={S.receipt}>
            <div style={S.receiptTop}>
              <div>
                <p style={S.receiptBadge}>RSVP receipt</p>
                <h2 style={S.receiptTitle}>{attending === "yes" ? "" : "We're sorry to hear that"}</h2>
                <p style={S.receiptSub}>
                  {attending === "yes"
                    ? "Your attendance and guest details have been saved."
                    : "Your decline has been recorded with your message."}
                </p>
              </div>
              <div style={{ textAlign:"right" }}>
                <p style={S.receiptBadge}>Frances &amp; Grant</p>
                <p style={{ ...S.receiptSub, marginTop:2 }}>4 October 2026</p>
              </div>
            </div>
            <hr style={S.receiptRule} />
            <div style={S.receiptGrid}>
              {[
                buildReceiptLine("Email", email),
                buildReceiptLine("Attendance", attending === "yes" ? "Joyfully accepts" : "Regretfully declines"),
                buildReceiptLine("Guest count", `${guests.length} ${guests.length === 1 ? "guest" : "guests"}`),
                buildReceiptLine("Message", receiptMessage),
              ].map((item) => (
                <div key={item.label} style={S.receiptRow}>
                  <p style={S.receiptLabel}>{item.label}</p>
                  <p style={S.receiptValue}>{item.value}</p>
                </div>
              ))}
              {attending === "yes" && (
                <div style={S.receiptRow}>
                  <p style={S.receiptLabel}>Guests</p>
                  <div style={S.receiptGuests}>
                    {receiptGuests.map((guest) => (
                      <div key={guest.label} style={S.receiptGuest}>
                        <p style={{ ...S.receiptValue, marginBottom:4, fontWeight:500 }}>{guest.label}</p>
                        <p style={S.receiptValue}>{guest.name}</p>
                        <p style={{ ...S.receiptValue, marginTop:2, color:"#7a5c4e" }}>{guest.dietary}</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
          <p style={{ fontFamily:"'Lora',serif", fontSize:16, color:"#7a5c4e", textAlign:"center", maxWidth:380, margin:0 }}>
            {attending==="yes" ? "Thank you for your RSVP. We can't wait to celebrate with you." : "Thank you for letting us know. We'll be thinking of you."}
          </p>
        </div>
      </div>
    </div>
  );

  return (
    <div style={S.page}>
      <style>{globalStyles}</style>

      <a href="/photos" style={S.eventPhotosBanner}>
        <span>Event photos</span>
        <span aria-hidden="true" style={S.eventPhotosArrow}>→</span>
      </a>

      {/* ── 1. HERO ── */}
      <div style={S.hero}>
        <div style={{ position:"absolute", left:0, bottom:0, width:"clamp(140px,22vw,220px)" }}>
          <CosmosFlower style={{ width:"100%", height:"auto" }}/>
        </div>
        <div style={S.heroContent} className="fade-up">
          <h1 style={S.scriptNames}>
            Frances<br/>
            <span style={{ fontSize:"0.58em", fontStyle:"italic", color:"#9b7b6a" }}>&amp;</span><br/>
            Grant
          </h1>
          <div style={{ marginTop:22 }}>
            <button className="rsvp-btn" onClick={() => window.location.href = "/photos"}>Access event photos</button>
          </div>
        </div>
      </div>

      {/* ── 2. TAGLINE ── */}
      <div style={S.taglineSection} className="fade-up delay-1">
        <WaterBlob color="#f0c8b8" width={220} height={130} style={{ position:"absolute", top:-10, right:-20 }}/>
        <WaterBlob color="#f0c8b8" width={160} height={90}  style={{ position:"absolute", bottom:-10, left:-10 }}/>
        <WaterBlob color="#b8ccc0" width={120} height={70}  style={{ position:"absolute", bottom:-5, right:40 }}/>
        <h2 style={S.tagline}>We hope you can<br/>share our big day<br/>with us!</h2>
      </div>

      {/* ── 3. WHEN ── */}
      <div style={S.blushSection} className="fade-up delay-2">
        <div style={{ position:"absolute", bottom:0, left:0, display:"flex", alignItems:"flex-end", gap:-8 }}>
          <PinkFlower size={90} style={{ marginBottom:-8 }}/>
          <PinkFlower size={68} style={{ marginBottom:-4, marginLeft:-18 }}/>
          <PinkFlower size={52} style={{ marginBottom:8, marginLeft:-12 }}/>
        </div>
        <div style={{ position:"absolute", top:16, right:"clamp(16px,8vw,80px)" }}>
          <PinkFlower size={48}/>
        </div>
        <div className="when-where-grid" style={{ display:"flex", alignItems:"center", gap:40, justifyContent:"center", maxWidth:680, margin:"0 auto", padding:"2.5rem 2rem 3rem" }}>
          <div style={{ flex:1, minWidth:220 }}>
            <p style={S.scriptLabel}>When?</p>
            <p style={S.bodyText}>Sunday 4<sup>th</sup> October 2026</p>
            <p style={S.bodyText}>Ceremony to commence at 5pm so<br/>please arrive by 4.45pm.</p>
            <p style={S.bodyText}>Dinner and dancing to follow.</p>
          </div>
          <TiltedPhoto src={BRIDGE_IMG} rotate={3}/>
        </div>
      </div>

      {/* ── 4. WHERE + DRESS CODE ── */}
      <div style={S.blushSection} className="fade-up delay-2">
        <div style={{ position:"absolute", top:16, left:16 }}>
          <PinkFlower size={56}/>
        </div>
        <div style={{ position:"absolute", bottom:0, right:0, display:"flex", alignItems:"flex-end" }}>
          <PinkFlower size={90} style={{ marginBottom:-12 }}/>
          <PinkFlower size={62} style={{ marginBottom:-4, marginLeft:-20 }}/>
        </div>
        <div className="where-dress-grid" style={{ display:"flex", alignItems:"center", gap:40, justifyContent:"center", maxWidth:680, margin:"0 auto", padding:"2.5rem 2rem 3rem" }}>
          <TiltedPhoto src={VENUE_IMG} rotate={-2.5}/>
          <div style={{ flex:1, minWidth:220 }}>
            <p style={S.scriptLabel}>Where?</p>
            <p style={S.bodyText}>Bougainvillea House</p>
            <p style={S.bodyText}>Howard Smith Wharves,</p>
            <p style={S.bodyText}>5 Boundary St.,</p>
            <p style={{ ...S.bodyText, marginBottom:24 }}>Brisbane City, QLD.</p>
            <p style={S.scriptLabel}>Dress Code?</p>
            <p style={S.bodyText}>Jacket and Tie</p>
          </div>
        </div>
      </div>

      {/* ── 5. GETTING HERE ── */}
      <div style={S.sageSection}>
        <div style={{ maxWidth:860, margin:"0 auto", padding:"3rem 2rem" }}>
          <div className="transport-grid" style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr", gap:32 }}>
            <TransportBlock icon={<WalkIcon/>} title="WALKING">
              The City Reach Boardwalk connects Howard Smith Wharves with the Riverside and Eagle Street Pier precincts (800m and 950m respectively). The Riverwalk is a 870m overwater shared walkway and cycleway directly joining New Farm and HSW. Guests arriving from the clifftop on Bowen Terrace are encouraged to use the East Lift for access to Bougainvillea House.
            </TransportBlock>
            <TransportBlock icon={<CarIcon/>} title="DRIVING">
              Guest set-down is available at the Drop Off point in front of the Crystalbrook Vincent Hotel. This can be accessed by the Main Entry to the precinct at 5 Boundary Street, Brisbane. Secure Parking operates a public car park offering 350+ car spaces. Book online prior to arrival to ensure you secure a space and receive discounted rates.
            </TransportBlock>
            <TransportBlock icon={<TaxiIcon/>} title="TAXI OR UBER">
              Direct drivers to Bowen Terrace (corner Kent Street) and take the East Lift from the clifftop down to the precinct. Alternatively, there is a set down zone available at the Drop Off point in front of the Hotel which is accessible by the Main Entry to the precinct at 5 Boundary Street, Brisbane.
            </TransportBlock>
            <TransportBlock icon={<FerryIcon/>} title="FERRY">
              Take a trip along the river direct to HSW. The CityHopper and Cross River Ferry run every 30 minutes from the HSW Ferry Terminal. Travel across the river between 6am and midnight.
            </TransportBlock>
          </div>
        </div>
      </div>

      {/* ── 6. MAP ── */}
      <div style={{ background:"#fdf6f0", padding:"2rem" }}>
        <div style={{ maxWidth:860, margin:"0 auto" }}>
          <img src={MAP_IMG} alt="Bougainvillea House Guest Access Map"
            style={{ width:"100%", borderRadius:8, boxShadow:"0 2px 16px rgba(0,0,0,0.08)" }}/>
        </div>
      </div>

      {/* ── 7. CLOSING ── */}
      <div style={S.closingSection} className="fade-up delay-3">
        <h2 style={{ ...S.tagline, fontSize:"clamp(28px,7vw,44px)" }}>
          We can't wait to<br/>celebrate with you!
        </h2>
        <div style={{ marginTop:32 }}>
          <a href="/photos" style={{ textDecoration:"none" }}>
            <button className="rsvp-btn">Access event photos</button>
          </a>
        </div>
      </div>

      {/* ── RSVP MODAL ── */}
      {showForm && (
        <div style={S.modalOverlay} onClick={() => setShowForm(false)}>
          <div style={S.modalBox} onClick={e => e.stopPropagation()}>
            <button onClick={() => setShowForm(false)} style={S.closeBtn}>✕</button>
            <p style={S.modalEyebrow}>Frances &amp; Grant</p>
            <h2 style={S.modalTitle}>Will you be joining us?</h2>
            <p style={S.modalSub}>Please RSVP by 9th August, 2026</p>
            <br/>
            <form onSubmit={handleSubmit} noValidate>
              <Field label="Will you be attending?">
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
                  <AttendButton label="Joyfully accepts"     icon="♡" selected={attending==="yes"} variant="yes" onClick={() => setAttending("yes")}/>
                  <AttendButton label="Regretfully declines" icon="✕" selected={attending==="no"}  variant="no"  onClick={() => setAttending("no")}/>
                </div>
              </Field>
              <br/>
              <Field label="Email address - for confirmation only">
                <input style={S.input} type="email" placeholder="example@domain.com" value={email} onChange={e => setEmail(e.target.value)} required/>
              </Field>
              {attending==="yes" && (
                <>
                  <Field label="Number of guests attending (including yourself)">
                    <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                      {[1,2,3,4,5].map(n => (
                        <button key={n} type="button" onClick={() => handleGuestCountChange(n)}
                          style={{ width:36, height:36, borderRadius:"50%", border:"1px solid",
                            borderColor: guestCount===n?"#9b7b6a":"#ddd0c6",
                            background:  guestCount===n?"#9b7b6a":"#fff",
                            color:       guestCount===n?"#fff":"#7a5c4e",
                            fontFamily:"'Inter',sans-serif", fontSize:13, cursor:"pointer", transition:"all 0.15s" }}>
                          {n}
                        </button>
                      ))}
                    </div>
                  </Field>
                  <div style={{ margin:"0.5rem 0 1rem" }}>
                    {guests.map((g,i) => <GuestRow key={i} index={i} guest={g} onChange={handleGuestChange}/>)}
                  </div>
                </>
              )}
              <Field label={<>Message <span style={{ color:"#b4a090" }}>(optional)</span></>}>
                <textarea style={{ ...S.input, resize:"vertical" }} rows={3} placeholder="Share your wishes…" value={message} onChange={e => setMessage(e.target.value)}/>
              </Field>
              {error && <p style={{ color:"#9b3a3a", fontSize:13, marginBottom:10, fontFamily:"'Inter',sans-serif" }}>{error}</p>}
              <button type="submit" disabled={!canSubmit}
                style={{ ...S.submitBtn, opacity:canSubmit?1:0.45, cursor:canSubmit?"pointer":"not-allowed" }}>
                {loading ? "Sending…" : "Send your RSVP"}
              </button>
            </form>
          </div>
        </div>
      )}

      <footer style={{ padding:"2rem 1rem", textAlign:"center", fontFamily:"'Inter', sans-serif", fontSize:"12px", color:"#9b7b6a", borderTop:"1px solid #efe4db", marginTop:"3rem" }}>
        Developed by{" "}
        <a href="https://yourwebsite.com" target="_blank" rel="noopener noreferrer"
          style={{ color:"#7a5c4e", textDecoration:"none", fontWeight:500 }}>
          Marcus McCarthy
        </a> in React ⚛️
      </footer>
    </div>
  );
}

// ── Transport icons ──────────────────────────────────────────────────────────

