function TransportBlock({ icon, title, children }) {
  return (
    <div style={{ textAlign:"center" }}>
      <div style={{ display:"flex", justifyContent:"center", alignItems:"center", height:56, marginBottom:10 }}>
        {icon}
      </div>
      <p style={{ fontFamily:"'Inter',sans-serif", fontSize:11, letterSpacing:"0.16em", color:"#5a4035", fontWeight:500, margin:"0 0 10px", textTransform:"uppercase" }}>{title}</p>
      <p style={{ fontFamily:"'Inter',sans-serif", fontSize:12, color:"#5a4035", lineHeight:1.7, margin:0, fontWeight:300 }}>{children}</p>
    </div>
  );
}

function Field({ label, children }) {
  return (
    <div style={{ marginBottom:"1rem" }}>
      <label style={{ fontSize:12, color:"#7a5c4e", display:"block", marginBottom:5, fontFamily:"'Inter',sans-serif", letterSpacing:"0.04em" }}>{label}</label>
      {children}
    </div>
  );
}

function AttendButton({ label, icon, selected, variant, onClick }) {
  const sel = variant==="yes"
    ? { background:"#e8f4ee", borderColor:"#7abf9a", color:"#2d6b4a" }
    : { background:"#f4ede9", borderColor:"#c4a89a", color:"#5a3a2e" };
  return (
    <button type="button" onClick={onClick}
      style={{ background:"#fff", border:"1px solid #d8ccc4", borderRadius:8, padding:"12px 8px",
               textAlign:"center", cursor:"pointer", fontSize:13, color:"#7a5c4e",
               fontFamily:"'Inter',sans-serif", transition:"all 0.15s", ...(selected?sel:{}) }}>
      <span style={{ fontSize:18, display:"block", marginBottom:4 }}>{icon}</span>
      {label}
    </button>
  );
}

